/* Prints static_asserts that pin recomp::guest structs (ddraw_types.h) to the
   real 32-bit SDK layout. Build with i686-w64-mingw32-gcc, run under wine;
   see README. Dev-time only. */
#define DIRECTDRAW_VERSION 0x0700
#define DIRECT3D_VERSION 0x0700
#include <windows.h>
#include <ddraw.h>
#include <d3d.h>
#include <stddef.h>
#include <stdio.h>

#define S(T) printf("static_assert(sizeof(" #T ") == %u, \"" #T " size\");\n", (unsigned)sizeof(T))
#define F(T, ours, sdk) printf("static_assert(offsetof(" #T ", " #ours ") == %u, \"" #T "." #ours "\");\n", (unsigned)offsetof(T, sdk))

int main(void) {
  printf("// Generated by tools/layout/ddraw_layout.c from the mingw-w64 SDK\n"
         "// headers (32-bit). Do not edit; regenerate per tools/layout/README.\n");
#include "fields.inc"
  return 0;
}
